package com.shatteredpixel.shatteredpixeldungeon.apd.difficulty;
import com.shatteredpixel.shatteredpixeldungeon.Dungeon;
import com.shatteredpixel.shatteredpixeldungeon.actors.blobs.*;
import com.shatteredpixel.shatteredpixeldungeon.items.Item;
import com.shatteredpixel.shatteredpixeldungeon.items.potions.brews.InfernalBrew;
import com.watabou.utils.*;
import org.junit.*;
import static org.junit.Assert.*;
public class InfernoSourceSafetyTest {
 FireCallerProvenanceTest fixture=new FireCallerProvenanceTest();java.lang.reflect.Field user;Object prior;
 @Before public void setup()throws Exception{fixture.setup();fixture.fixture.rules(200,300,500);user=Item.class.getDeclaredField("curUser");user.setAccessible(true);prior=user.get(null);user.set(null,Dungeon.hero);}
 @After public void cleanup()throws Exception{user.set(null,prior);fixture.cleanup();}
 @Test public void invalidMixturesDoNotMutateExistingFireOrCreateNewFields(){Fire f=Fire.seedAttributed(312,4,OffensiveDamageOrigin.BOSS);int[] before=f.cur.clone();int volume=f.volume;for(double[] bad:new double[][]{null,new double[]{1,0},new double[]{0,-1,0,2},new double[]{0,0,0,0},new double[]{Double.NaN,0,0,1}}){try{Fire.seedAttributedMixture(312,4,bad);fail();}catch(IllegalArgumentException expected){}assertArrayEquals(before,f.cur);assertEquals(volume,f.volume);}Dungeon.level.blobs=new java.util.HashMap<>();try{Fire.seedAttributedMixture(312,4,new double[]{0,-1,0,2});fail();}catch(IllegalArgumentException expected){}assertFalse(Dungeon.level.blobs.containsKey(Fire.class));}
 @Test public void explicitMixtureIsIndependentOfUnrelatedOuterEffectContext()throws Exception{Fire f=Fire.seedAttributed(312,4,OffensiveDamageOrigin.BOSS);try(OffensiveEffectContext c=OffensiveEffectContext.enter(OffensiveDamageOrigin.ENEMY)){Fire.seedAttributedMixture(312,4,new double[]{0,.5,0,.5});assertEquals(OffensiveDamageOrigin.ENEMY,OffensiveEffectContext.current());}assertEquals(8,f.cur[312]);assertEquals(17,fixture.burn(f));assertEquals(OffensiveDamageOrigin.UNATTRIBUTED,OffensiveEffectContext.current());}
 @Test public void realBrewThrowUsesCapturedBossInsteadOfStaleGlobalHero()throws Exception{new InfernalBrew().apdThrowAttributed(312,OffensiveDamageOrigin.BOSS);Inferno i=(Inferno)Dungeon.level.blobs.get(Inferno.class);assertNotNull(i);assertEquals(20,infernoBurn(i));}
 @Test public void explosionTriggeredBrewUsesItsTriggerAndUnownedBrewDoesNotInventHero()throws Exception{try(OffensiveEffectContext c=OffensiveEffectContext.enter(OffensiveDamageOrigin.BOSS)){new InfernalBrew().shatter(312);}assertEquals(20,infernoBurn((Inferno)Dungeon.level.blobs.get(Inferno.class)));Dungeon.level.blobs=new java.util.HashMap<>();new InfernalBrew().shatter(312);assertEquals(4,infernoBurn((Inferno)Dungeon.level.blobs.get(Inferno.class)));}
 @Test public void restoredCenserInfernoKeepsRecordedCreatorAfterGlobalUserChanges()throws Exception{Dungeon.hero.sprite=new SpecialBombDamageProvenanceTest.Quiet();new com.watabou.noosa.Group().add(Dungeon.hero.sprite);Dungeon.hero.pos=260;com.shatteredpixel.shatteredpixeldungeon.items.trinkets.ChaoticCenser.GasSpewer pending=new com.shatteredpixel.shatteredpixeldungeon.items.trinkets.ChaoticCenser.GasSpewer();assertTrue(pending.attachTo(Dungeon.hero));pending.set(312,Inferno.class,120);Bundle saved=new Bundle();pending.storeInBundle(saved);pending.detach();Dungeon.hero.apdInheritOffensiveOrigin(new com.shatteredpixel.shatteredpixeldungeon.actors.mobs.Goo());com.shatteredpixel.shatteredpixeldungeon.items.trinkets.ChaoticCenser.GasSpewer restored=new com.shatteredpixel.shatteredpixeldungeon.items.trinkets.ChaoticCenser.GasSpewer();restored.restoreFromBundle(saved);assertTrue(restored.attachTo(Dungeon.hero));restored.act();assertEquals(8,infernoBurn((Inferno)Dungeon.level.blobs.get(Inferno.class)));}
 int infernoBurn(Inferno i){SpecialBombDamageProvenanceTest.Target t=new SpecialBombDamageProvenanceTest.Target(false);com.shatteredpixel.shatteredpixeldungeon.actors.Actor.add(t);try{i.act();com.shatteredpixel.shatteredpixeldungeon.actors.buffs.Burning b=t.buff(com.shatteredpixel.shatteredpixeldungeon.actors.buffs.Burning.class);assertNotNull(b);Bundle state=new Bundle();b.storeInBundle(state);state.put("next_dmg",4);b.restoreFromBundle(state);b.act();assertEquals(1,t.hits.size());assertSame(b,t.sources.get(0));return t.hits.get(0);}finally{com.shatteredpixel.shatteredpixeldungeon.actors.Actor.remove(t);}}
}
